V C_Campaign::m_choose_reward(const Args& A) {
    V L_key = A.get(0, SY("key"), nullptr, "choose_reward");
    V L_dependency;
    V L_won_today;
    if ((!py_is(L_key, V::none()) && !(pm_pve::f_campaign_card_allowed(Args{L_key, a_coop})).truthy())) {
        return (((V((isinstance(L_key, "str")))).truthy() && py::in(L_key, pm_catalog::CARDS)) ? V(pm_pve::f_disabled_message(Args{a_coop})) : V(SV("奖励卡无效")));
    }
    L_won_today = py::bool_(py_and(a_history, [&]() -> V { return py_and(V((py::m_get(rd(a_history, V(-1.0)), SV("result")) == SV("win"))), [&]() -> V { return V((py::m_get(rd(a_history, V(-1.0)), SV("day")) == a_day)); }); }));
    if ((!(a_rewards).truthy() && !(L_won_today).truthy())) {
        return SV("当前没有待领取的通关奖励");
    }
    if ((!py_is(L_key, V::none()) && !py::in(L_key, a_rewards))) {
        return SV("请选择奖励卡牌");
    }
    if (!py_is(L_key, V::none())) {
        (void)(py::m_append(a_unlocked, L_key));
    }
    a_rewards = V::list({});
    a_day = py::iadd(a_day, V(1.0));
    (void)(m_stock_shop(Args{}));
    if ((!py_is(L_key, V::none()) && (py::len(a_deck) < m_slots(Args{})))) {
        L_dependency = py::m_get(rd(pm_catalog::CARDS, L_key), SV("dependency"));
        if ((!(L_dependency).truthy() || py::in(L_dependency, a_deck))) {
            (void)(py::m_append(a_deck, L_key));
        }
    }
    (void)(m_fit_deck(Args{}));
    return SV("");
    return V::none();
}

